\title{Tightness of the Unit-Shift Bound for Euler's Totient Function:\\
Construction, Structure, and a Counting-Transfer Skeleton}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}

\begin{abstract}
We study the \emph{unit-shift totient equation} $\phitot(n) = \phitot(n+1)$,
where $\phitot$ denotes Euler's totient function, and its counting function
$\Sphi(x) = \#\{\, n \le x : \phitot(n) = \phitot(n+1)\,\}$.
A deep theorem of Graham, Holt, and Pomerance bounds this count above by
$x\exp\{-(\tfrac12 - o(1))\sqrt{\log x\,\log\log x}\}$, and the corresponding
\emph{tightness} statement asserts a matching lower bound
$\Sphi(x) \ge C\,x\exp\{-(\tfrac12 + o(1))\sqrt{\log x\,\log\log x}\}$.
We develop the constructive and structural backbone of this circle of ideas:
(1) a Fermat-prime family construction showing that if $F_0,\dots,F_{m-1}$ are
prime then $N_m=\prod_{k<m}F_k$ solves $\phitot(n)=\phitot(n+1)$ with both
totients equal to $2^{2^m-1}$; (2) the unconditional solution $N_5=2^{32}-1$ and
a proven conditional infinitude; (3) a counting-transfer theorem yielding the
unconditional bounds $\Sphi(194)\ge 6$ and $\Sphi(975)\ge 10$; and (4) a
structural analysis of solutions. All results are framed through the
multiplicativity of $\phitot$.
\end{abstract}

\maketitle

\section{Introduction}

Euler's totient function $\phitot(n)$ counts the integers in $\{1,\dots,n\}$
coprime to $n$. It is \emph{multiplicative}: $\phitot(ab)=\phitot(a)\phitot(b)$
whenever $\gcd(a,b)=1$, and on prime powers $\phitot(p^e)=p^{e-1}(p-1)$. These
facts determine $\phitot$ from a prime factorization.

Because $n$ and $n+1$ are coprime, they are built from disjoint sets of primes;
that two such numbers should have equal totient is a nontrivial multiplicative
coincidence. The set of $n$ with $\phitot(n)=\phitot(n+1)$ begins
$1,3,15,104,164,194,255,495,584,975,\dots$.

\paragraph{The Graham--Holt--Pomerance (GHP) bound.}
Writing $\log_2$ for $\log\log$, the GHP upper bound states
\[
  \Sphi(x) \ll x\exp\!\left\{-\left(\tfrac12 - o(1)\right)\sqrt{\log x \cdot \log_2 x}\,\right\}.
\]
The \emph{tightness} statement is the matching lower bound: there exists $C>0$
with
\[
  \Sphi(x) \ge C\,x\exp\!\left\{-\left(\tfrac12 + o(1)\right)\sqrt{\log x \cdot \log_2 x}\,\right\}
\]
for all sufficiently large $x$. A complete proof requires the anatomy of
integers, smooth-number estimates, and sieve methods. We isolate and prove the
constructive and structural skeleton underlying the lower-bound program.

\subsection{Notation}
$\phitot(n)$ is the totient; $F_k=2^{2^k}+1$ is the $k$-th Fermat number
($F_0=3,F_1=5,F_2=17,F_3=257,F_4=65537$ are the known Fermat primes);
$N_m=\prod_{k=0}^{m-1}F_k$; and $\Sphi(x)=\#\{n:1\le n\le x,\ \phitot(n)=\phitot(n+1)\}$.

\section{The Fermat-prime family construction}

\begin{lemma}[Telescoping successor]\label{lem:succ}
For every $m\ge 0$, $N_m+1=\prod_{k<m}F_k+1=2^{2^m}$.
\end{lemma}
\begin{proof}[Proof sketch]
The classical identity $\prod_{k<m}F_k=2^{2^m}-1$ follows by induction using
$(2^{2^m}-1)(2^{2^m}+1)=2^{2^{m+1}}-1$. Add $1$.
\end{proof}

\begin{lemma}\label{lem:Fsub1}
For every $k$, $F_k-1=2^{2^k}$.
\end{lemma}

\begin{lemma}\label{lem:prodsub1}
For every $m$,
$\prod_{k<m}(F_k-1)=\prod_{k<m}2^{2^k}=2^{\sum_{k<m}2^k}=2^{2^m-1}$.
\end{lemma}
\begin{proof}[Proof sketch]
Substitute Lemma~\ref{lem:Fsub1}, collect into one power, and evaluate the
geometric sum $\sum_{k<m}2^k=2^m-1$.
\end{proof}

\begin{lemma}\label{lem:tw}
For every $m$, $\phitot(2^{2^m})=2^{2^m-1}$.
\end{lemma}
\begin{proof}[Proof sketch]
Apply $\phitot(p^e)=p^{e-1}(p-1)$ with $p=2$, $e=2^m$.
\end{proof}

\begin{lemma}\label{lem:totfp}
If $F_0,\dots,F_{m-1}$ are all prime, then
$\phitot(N_m)=\prod_{k<m}(F_k-1)$.
\end{lemma}
\begin{proof}[Proof sketch]
Induct on $m$. Fermat numbers are pairwise coprime, so $N_m=N_{m-1}F_{m-1}$ is a
product of coprime factors and multiplicativity gives
$\phitot(N_m)=\phitot(N_{m-1})\phitot(F_{m-1})$. As $F_{m-1}$ is prime,
$\phitot(F_{m-1})=F_{m-1}-1$; the inductive hypothesis handles the rest.
\end{proof}

\begin{theorem}[Fermat-prime family construction]\label{thm:fam}
If the first $m$ Fermat numbers are all prime, then
$\phitot(N_m)=\phitot(N_m+1)$, both sides equal to $2^{2^m-1}$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemmas~\ref{lem:totfp} and \ref{lem:prodsub1}, $\phitot(N_m)=2^{2^m-1}$. By
Lemmas~\ref{lem:succ} and \ref{lem:tw}, $\phitot(N_m+1)=\phitot(2^{2^m})=2^{2^m-1}$.
\end{proof}

\begin{corollary}\label{cor:2pow32}
Since $F_0,\dots,F_4=3,5,17,257,65537$ are prime,
$N_5=2^{32}-1=4294967295$ satisfies
$\phitot(4294967295)=\phitot(4294967296)=2^{31}=2147483648$.
\end{corollary}

\begin{lemma}\label{lem:lefp}
For every $m$, $m\le N_m$.
\end{lemma}
\begin{proof}[Proof sketch]
From $N_m+1=2^{2^m}$ and $m+1\le 2^m\le 2^{2^m}$ (using $m<2^m$ twice).
\end{proof}

\begin{theorem}[Conditional infinitude]\label{thm:inf}
Suppose that for every $M$ there exists $m>M$ with $F_0,\dots,F_{m-1}$ all prime.
Then $\{\,n:\phitot(n)=\phitot(n+1)\,\}$ is infinite.
\end{theorem}
\begin{proof}[Proof sketch]
Given $M$, choose such $m>M$; then $N_m$ is a solution by Theorem~\ref{thm:fam}
and $N_m\ge m>M$ by Lemma~\ref{lem:lefp}. The solution set is unbounded.
\end{proof}

This is a proven implication; only its hypothesis is open.

\section{Structural constraints on solutions}

\begin{lemma}\label{lem:cop}
For every $n$, $\gcd(n,n+1)=1$.
\end{lemma}

\begin{lemma}[Parity of collision values]\label{lem:par}
If $n\ge 2$ and $\phitot(n)=\phitot(n+1)$, then $\phitot(n)$ is even.
\end{lemma}
\begin{proof}[Proof sketch]
Rewrite along the collision: $\phitot(n)=\phitot(n+1)$ with $n+1\ge 3$, and
$\phitot(m)$ is even for $m\ge 3$. The hypothesis is essential ($\phitot(2)=1$ is
odd, but $\phitot(2)\ne\phitot(3)$).
\end{proof}

\begin{lemma}\label{lem:succnp}
If $n\ge 2$ and $\phitot(n)=\phitot(n+1)$, then $n+1$ is not prime.
\end{lemma}
\begin{proof}[Proof sketch]
If $n+1$ were prime, $\phitot(n+1)=n$; but $\phitot(n)\le n-1<n$.
\end{proof}

\begin{lemma}\label{lem:nbp}
For $n\ge 3$, $n$ and $n+1$ are never both prime.
\end{lemma}

\begin{remark}[A false folklore rule]
It is sometimes claimed that any solution $n$ must be odd. This is false:
$n=104=2^3\cdot 13$ is even and
$\phitot(104)=2^2\cdot 12=48=(3-1)(5-1)(7-1)=\phitot(105)$.
\end{remark}

\section{The counting function and the transfer theorem}

\begin{definition}
$\Sphi(x)=\#\{\,n:1\le n\le x,\ \phitot(n)=\phitot(n+1)\,\}$.
\end{definition}

\begin{lemma}[Monotonicity]\label{lem:mono}
If $x\le y$ then $\Sphi(x)\le\Sphi(y)$.
\end{lemma}

\begin{lemma}[Trivial ceiling]\label{lem:ceil}
$\Sphi(x)\le x$.
\end{lemma}

\begin{lemma}[Strict non-saturation]\label{lem:nonsat}
For $x\ge 2$, $\Sphi(x)<x$.
\end{lemma}
\begin{proof}[Proof sketch]
$n=2$ is not a collision ($\phitot(2)=1\ne 2=\phitot(3)$), so the filtered set is
a proper subset of $\{1,\dots,x\}$.
\end{proof}

\begin{theorem}[Counting-transfer theorem]\label{thm:transfer}
Let $W$ be a finite set with, for every $w\in W$: $1\le w\le x$ and
$\phitot(w)=\phitot(w+1)$. Then $|W|\le\Sphi(x)$.
\end{theorem}
\begin{proof}[Proof sketch]
$W$ is a subset of the collision-filtered interval defining $\Sphi(x)$;
cardinality is monotone under inclusion.
\end{proof}

This converts any density-producing construction of certified witnesses directly
into a lower bound on $\Sphi$.

\begin{theorem}\label{thm:six}
$\Sphi(194)\ge 6$, certified by $W=\{1,3,15,104,164,194\}$.
\end{theorem}

\begin{theorem}\label{thm:ten}
$\Sphi(975)\ge 10$, certified by $W=\{1,3,15,104,164,194,255,495,584,975\}$.
\end{theorem}

\section{Multiplicative certification of witnesses}

Each witness is proved by factoring $n$ and $n+1$ into coprime prime powers and
applying multiplicativity, exhibiting a balance between a power of two and a
product of small odd primes.

\begin{center}
\begin{tabular}{rcccc}
\toprule
$n$ & $n$ & $n+1$ & common $\phitot$ & lemma \\
\midrule
15 & $3\cdot 5$ & $2^4$ & 8 & \texttt{ghp\_15} \\
104 & $2^3\cdot 13$ & $3\cdot 5\cdot 7$ & 48 & \texttt{ghp\_104} \\
164 & $2^2\cdot 41$ & $3\cdot 5\cdot 11$ & 80 & \texttt{ghp\_164} \\
194 & $2\cdot 97$ & $3\cdot 5\cdot 13$ & 96 & \texttt{ghp\_194} \\
255 & $3\cdot 5\cdot 17$ & $2^8$ & 128 & \texttt{ghp\_255} \\
495 & $3^2\cdot 5\cdot 11$ & $2^4\cdot 31$ & 240 & \texttt{ghp\_495} \\
584 & $2^3\cdot 73$ & $3^2\cdot 5\cdot 13$ & 288 & \texttt{ghp\_584} \\
975 & $3\cdot 5^2\cdot 13$ & $2^4\cdot 61$ & 480 & \texttt{ghp\_975} \\
\bottomrule
\end{tabular}
\end{center}

For example, $255=3\cdot5\cdot17$ gives $\phitot(255)=2\cdot4\cdot16=128$, while
$256=2^8$ gives $\phitot(256)=2^7=128$.

\section{Discussion}

The mathematics splits into four strata: \emph{build by hand} (the Fermat
construction and multiplicative witnesses); \emph{constrain} (parity and
primality obstructions, which force $\Sphi(x)<x$); \emph{transfer}
(Theorem~\ref{thm:transfer}, separating construction from counting); and
\emph{measure} (the GHP asymptotic and its tightness, requiring analytic
machinery). The transfer theorem is the reusable engine: the analytic difficulty
of the full tightness theorem is concentrated entirely in producing a dense
witness family.

\section{Future work}

\begin{itemize}
\item \textbf{A second one-parameter family.} Seek an infinite family
$\phitot(2^a m)=\phitot(2^b m')$ with $m,m'$ products of distinct small odd
primes balancing $\prod(1-1/p)$ across a power-of-two carry; the witnesses
$104,164,194,495,584,975$ are instances.
\item \textbf{Effective polynomial lower bound.} Prove $\Sphi(x)\ge x^c$ for
explicit $c>0$ via a constructive family; Theorem~\ref{thm:transfer} reduces this
to a counting estimate.
\item \textbf{Unconditional infinitude.} Replace the unknown supply of Fermat
primes by a proven-infinite supply of admissible balancing primes so the
telescoping runs forever, giving $\Sphi(x)\to\infty$.
\end{itemize}

\section{Conclusion}

We have formalized the constructive and structural backbone of the tightness
statement: an exact Fermat-prime family with both totients $2^{2^m-1}$, the
unconditional solution $2^{32}-1$, a proven conditional infinitude, a complete
elementary structure theory, and a counting-transfer theorem yielding
$\Sphi(194)\ge 6$ and $\Sphi(975)\ge 10$. The remaining gap to full tightness is
the production of a dense infinite witness family --- the analytic heart of the
Graham--Holt--Pomerance result.

\end{document}

