from typing import Dict

def prime_factorization(n: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d, m = 2, n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def totient(n: int) -> int:
    if n == 1:
        return 1
    result = 1
    for p, e in prime_factorization(n).items():
        result *= p ** (e - 1) * (p - 1)
    return result

def certify_collision(n: int) -> bool:
    return totient(n) == totient(n + 1)

from typing import Tuple

def fermat_number(k: int) -> int:
    return 2 ** (2 ** k) + 1

def fermat_family_solution(m: int) -> Tuple[int, int]:
    N = 1
    for k in range(m):
        N *= fermat_number(k)
    assert N + 1 == 2 ** (2 ** m)
    common_totient = 2 ** (2 ** m - 1)
    return N, common_totient

